from datetime import date, timedelta

def make_incident(i, title, service, severity, category, root, symptoms, steps, resolution, lesson, days, duration):
    iid=f"INC-{2400+i}"
    return {"id":iid,"kind":"incident","title":title,"service":service,"severity":severity,"category":category,"date":(date.today()-timedelta(days=days)).isoformat(),"root_cause":root,"resolution":resolution,"duration_minutes":duration,"content":f"Incident {iid}: {title}. Service: {service}. Severity: {severity}. Category: {category}. Date: {(date.today()-timedelta(days=days)).isoformat()}. Symptoms: {symptoms}. Root cause: {root}. Investigation steps: {steps}. Resolution: {resolution}. Lessons learned: {lesson}."}

INCIDENTS = [
make_incident(1,"Checkout requests timing out","checkout-api","SEV-1","Database","Database connection pool exhausted after a traffic spike; connections were held during slow downstream calls.","Elevated checkout latency, SQLAlchemy pool timeout errors, intermittent 503s.","Compared pool checkout wait with active connection count; inspected slow request traces; found downstream call inside transaction.","Raised pool capacity temporarily, moved remote call outside transaction, and added pool saturation alert.","Bound connection lifetime and alert before saturation; load test peak concurrency.",2,47),
make_incident(2,"Order API connection timeouts","orders-api","SEV-1","Database","Database connection pool exhausted because workers exceeded the configured pool plus overflow.","HTTP 5xx spikes with QueuePool timeout; database itself had spare CPU.","Checked pool metrics per pod; correlated rollout to worker count increase; reproduced connection demand.","Reduced worker count, tuned pool size and overflow, added connection checkout histogram.","Scale database connections and app concurrency together; pool capacity is per process.",11,63),
make_incident(3,"Payment service DB pool saturation","payments-api","SEV-2","Database","Connection pool exhaustion caused by leaked sessions on exception paths.","Pool reached max size and requests waited 30 seconds before failing.","Inspected session lifecycle; traced exception handler that skipped close; verified with pool checkout logs.","Added request-scoped session cleanup and restarted affected workers.","Exercise cleanup paths in integration tests and monitor checked-out connections.",22,81),
make_incident(4,"Search endpoint p99 regression","catalog-api","SEV-2","Database","A sequential scan on products was introduced when a filter shipped without a composite index.","Search p99 rose from 180ms to 4.8s; database CPU climbed.","Reviewed query plan; compared production SQL with index definitions; sampled slow query log.","Created a composite index on tenant_id and updated_at; verified query plan switched to index scan.","Require query-plan review for high-volume filters and track index coverage.",7,54),
make_incident(5,"Inventory query saturation","inventory-api","SEV-2","Database","Missing index on warehouse_id caused full scans under replenishment traffic.","Inventory reads timed out; read replica CPU at 95%.","Grouped slow logs by fingerprint; ran EXPLAIN ANALYZE; measured rows examined.","Added warehouse_id, sku index and capped batch size.","Replay realistic cardinalities in staging before query launch.",34,92),
make_incident(6,"Checkout API returning 503","checkout-api","SEV-1","API","Database pool exhaustion recurred after a new worker deployment doubled per-pod connection demand.","503s coincide with checkout timeouts; DB CPU normal; connections at configured max.","Compared deployment diff; calculated total pools across replicas; checked Hikari pending threads.","Rolled back worker increase, then set global connection budget and pool metrics alert.","Per-replica pool defaults multiply quickly; enforce an organization-wide connection budget.",15,39),
make_incident(7,"Gateway 5xx after release","edge-gateway","SEV-1","Deployment","New retry policy amplified upstream failures into a retry storm.","Gateway 502/503, upstream request volume tripled, latency cascaded.","Compared retry counters before/after release; inspected trace fan-out; checked circuit breaker state.","Rolled back retry policy and restored bounded exponential backoff with jitter.","Retries need budgets, jitter and circuit breaking; validate under partial failure.",5,31),
make_incident(8,"Profile API request timeouts","profile-api","SEV-2","API","A synchronous call to a slow identity provider blocked the request worker pool.","Requests timed out at 30 seconds; worker utilization 100%; provider latency elevated.","Compared app and provider timings; thread dump showed blocked outbound calls.","Moved identity sync to a queue and set a 2-second outbound timeout.","Isolate third-party latency from user-facing request capacity.",41,76),
make_incident(9,"Recommendation pods OOMKilled","recommendation-worker","SEV-2","Memory","Unbounded in-memory batch accumulation caused a memory leak during catalog refresh.","Pods restarted repeatedly with memory climbing until OOMKilled.","Reviewed heap profile and batch loop; measured resident set across refresh cycle.","Streamed batches in bounded chunks and set memory request/limit based on profile.","Long-running workers need heap growth alerts and bounded queues.",9,69),
make_incident(10,"API workers killed after deploy","reporting-api","SEV-2","Memory","A new response cache retained large payloads without eviction.","RSS rose steadily; Kubernetes OOMKilled workers shortly after deployment.","Compared heap snapshots; disabled cache to confirm; traced retained response objects.","Rolled back cache, added size-bounded LRU and memory dashboards.","Cache memory must have explicit limits and representative soak testing.",28,43),
make_incident(11,"Production rollout returned 500s","checkout-api","SEV-1","Deployment","Schema migration deployed after application code assumed a newly added column.","New pods emitted missing-column errors; old pods remained healthy.","Checked rollout timeline and migration status; inspected failing SQL and pod versions.","Rolled back application, applied backward-compatible migration, redeployed in expand-migrate-contract order.","Keep schema changes compatible across mixed-version rollouts.",18,52),
make_incident(12,"TLS handshake failures for webhooks","webhook-service","SEV-2","Certificates","Public TLS certificate expired because renewal job failed after DNS challenge credentials rotated.","Clients saw certificate expired; internal health check used HTTP and stayed green.","Checked certificate chain and expiry; inspected cert-manager events and DNS provider logs.","Restored DNS credentials, renewed certificate, and added expiry probes from outside the cluster.","Alert on certificate expiry and validate the full external TLS path.",12,36),
make_incident(13,"Internal service discovery outage","platform-dns","SEV-1","DNS","CoreDNS pods exhausted CPU due to a malformed search-domain retry loop.","Inter-service lookups timed out across multiple namespaces.","Checked DNS latency metrics; queried CoreDNS logs; bypassed DNS to isolate application health.","Reverted resolver config and scaled CoreDNS while removing redundant search suffixes.","Test resolver config changes and alert on SERVFAIL and p95 lookup latency.",48,58),
make_incident(14,"Cart reads failing intermittently","cart-api","SEV-2","Cache","Redis failover left clients pinned to the old primary endpoint.","Redis connection resets and cache miss spike; database read load increased.","Compared client endpoint with cluster primary; inspected sentinel failover and pool refresh behavior.","Enabled topology refresh, recycled stale connections and warmed hot keys.","Clients must discover primary changes and database fallback needs a load limit.",3,44),
make_incident(15,"Session cache unavailable","identity-api","SEV-1","Cache","Redis maxmemory policy was set to noeviction and a key buildup exhausted memory.","SET commands failed with OOM; login sessions could not be written.","Checked Redis INFO memory and eviction policy; identified expired-key retention issue.","Set allkeys-lru policy, cleaned stale keys, and added memory headroom alerts.","Set capacity and eviction policy per workload semantics; monitor key growth.",25,71),
make_incident(16,"Event processing lag rising","billing-consumer","SEV-2","Queue","Consumer concurrency dropped after a deployment changed partition assignment and one partition became hot.","Queue lag exceeded 45 minutes; throughput fell despite healthy brokers.","Compared lag by partition; inspected consumer rebalance and processing duration.","Rebalanced partitions, restored concurrency, and made handler idempotent before parallelizing.","Track per-partition lag and test rebalances with production-like key skew.",6,87),
make_incident(17,"Log volume filled node disks","observability-agent","SEV-2","Storage","Debug logging was enabled in production and log rotation was misconfigured.","Node disk reached 100%; pods evicted; writes failed.","Checked node filesystem and largest paths; traced log volume to debug setting.","Disabled debug logs, reclaimed rotated files, and fixed retention and disk alerts.","Disk alerts need actionable thresholds and rotation tests.",19,49),
make_incident(18,"Public API throttling legitimate traffic","api-gateway","SEV-2","Rate limiting","A per-IP rate limit treated all NATed enterprise traffic as a single client.","429 rate increased after enterprise office egress change.","Segmented 429s by client IP and tenant; checked limiter key and trusted proxy chain.","Changed limiter key to authenticated tenant and added a safe burst allowance.","Rate limits should use identity appropriate to the product and expose rejection metrics.",31,33),
make_incident(19,"Worker cannot connect to database","email-worker","SEV-2","Configuration","Production DATABASE_URL secret referenced the staging hostname after a secret rotation.","New workers failed DNS resolution for the database; existing pods were unaffected.","Compared pod environment with secret versions; checked DNS and deployment revision.","Restored production secret, restarted workers, and added startup dependency validation.","Validate configuration source and target environment before rollout.",10,29),
make_incident(20,"Fraud checks timing out","risk-api","SEV-2","Third-party","Third-party risk API suffered a regional outage and our client had no circuit breaker.","Risk checks exceeded timeout; checkout queued while calls accumulated.","Checked provider status and outbound traces; disabled retries to stop request pileup.","Activated fail-open policy for low-risk orders and queued deferred checks.","Define dependency-specific fallback and test provider outage drills.",14,66),
make_incident(21,"Database pool exhaustion during campaign","checkout-api","SEV-1","Database","A campaign traffic surge exhausted connection pools; long-running report queries competed with checkout.","Checkout 503s with connection acquisition waits; OLTP latency correlated with reports.","Correlated connection waits to report jobs; inspected max pool utilization and query age.","Paused report jobs, increased pool within DB limit, and isolated analytics workload.","Separate analytical traffic and maintain a tested traffic-surge playbook.",55,73),
make_incident(22,"Account lookup slow after launch","identity-api","SEV-2","Database","Missing index on normalized_email caused table scan after customer growth.","Login p95 climbed above 3 seconds; DB read IOPS saturated.","Used query stats and EXPLAIN; compared row growth since prior index review.","Added functional index and verified case-insensitive lookup plan.","Revisit query plans as data cardinality changes.",62,102),
make_incident(23,"Queue backlog after provider recovery","notifications","SEV-3","Queue","Consumers remained paused after a third-party API recovered, and backlog alert had no paging route.","Notifications delayed by two hours while brokers remained healthy.","Checked consumer group state; verified provider recovery; inspected alert routing.","Resumed consumers with controlled concurrency and paged backlog threshold.","Recovery playbooks must include safe replay and alert ownership.",37,115),
make_incident(24,"Static assets returning 503","media-api","SEV-2","Storage","Temporary volume filled during image processing because cleanup missed failed jobs.","Upload endpoints failed; disk usage grew after retries.","Inspected volume usage and failed-job directories; reproduced cleanup exception.","Removed orphan temp files and made cleanup run in finally block.","Bound temporary storage and test cleanup during worker termination.",44,57),
]

